{
  description = "Kassiber release packages";

  inputs.nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

  outputs = { self, nixpkgs }:
    let
      system = "x86_64-linux";
      pkgs = import nixpkgs { inherit system; };
      inherit (pkgs) lib;

      cli = pkgs.stdenvNoCC.mkDerivation {
        pname = "kassiber-cli";
        version = "1.2.3";
        src = pkgs.fetchurl {
          url = "https://github.com/bitcoinaustria/kassiber/releases/download/v1.2.3/kassiber-cli-linux-x64.tar.gz";
          sha256 = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
        };
        sourceRoot = "kassiber-cli-linux-x64";
        nativeBuildInputs = [ pkgs.autoPatchelfHook ];
        buildInputs = [ pkgs.stdenv.cc.cc.lib ];
        installPhase = ''
          runHook preInstall
          # The binary finds the AI provider broker beside its executable.
          install -Dpm755 kassiber "$out/libexec/kassiber-cli/kassiber"
          install -Dpm644 provider_broker/index.mjs             "$out/libexec/kassiber-cli/provider_broker/index.mjs"
          mkdir -p "$out/bin"
          ln -s "$out/libexec/kassiber-cli/kassiber" "$out/bin/kassiber"
          install -Dpm644 ${./LICENSE}             "$out/share/licenses/kassiber-cli/LICENSE"
          runHook postInstall
        '';
        meta = {
          description = "Local-first Bitcoin accounting CLI";
          homepage = "https://github.com/bitcoinaustria/kassiber";
          license = lib.licenses.mit;
          platforms = [ "x86_64-linux" ];
          sourceProvenance = [ lib.sourceTypes.binaryNativeCode ];
          mainProgram = "kassiber";
        };
      };

      desktopSrc = pkgs.fetchurl {
        url = "https://github.com/bitcoinaustria/kassiber/releases/download/v1.2.3/kassiber-linux-x64.AppImage";
        sha256 = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
      };
      desktopContents = pkgs.appimageTools.extractType2 {
        pname = "kassiber";
        src = desktopSrc;
        version = "1.2.3";
      };
      desktop = pkgs.appimageTools.wrapType2 {
        pname = "kassiber";
        version = "1.2.3";
        src = desktopSrc;
        nativeBuildInputs = [ pkgs.makeWrapper ];
        extraPkgs = pkgs: with pkgs; [ gtk3 webkitgtk_4_1 ];
        extraInstallCommands = ''
          mv "$out/bin/kassiber" "$out/bin/kassiber-ui"
          makeWrapper "$out/bin/kassiber-ui" "$out/bin/kassiber"             --add-flags "--cli"
          install -Dpm644 ${./LICENSE}             "$out/share/licenses/kassiber/LICENSE"
          desktop_file=""
          for candidate in             "${desktopContents}/Kassiber.desktop"             "${desktopContents}/usr/share/applications/Kassiber.desktop"; do
            if [ -f "$candidate" ]; then
              desktop_file="$candidate"
              break
            fi
          done
          if [ -n "$desktop_file" ]; then
            install -Dpm644 "$desktop_file"               "$out/share/applications/Kassiber.desktop"
            sed -i               's|^Exec=[^[:space:]]*|Exec=kassiber-ui|'               "$out/share/applications/Kassiber.desktop"
          fi
          for size in 32x32 128x128 256x256@2; do
            icon="${desktopContents}/usr/share/icons/hicolor/$size/apps/kassiber-ui.png"
            if [ -f "$icon" ]; then
              install -Dpm644 "$icon"                 "$out/share/icons/hicolor/$size/apps/kassiber-ui.png"
            fi
          done
        '';
        meta = {
          description = "Local-first Bitcoin accounting suite";
          homepage = "https://github.com/bitcoinaustria/kassiber";
          license = lib.licenses.mit;
          platforms = [ "x86_64-linux" ];
          sourceProvenance = [ lib.sourceTypes.binaryNativeCode ];
          mainProgram = "kassiber-ui";
        };
      };
    in {
      packages.${system} = {
        inherit cli desktop;
        default = desktop;
      };
      apps.${system} = {
        default = { type = "app"; program = "${desktop}/bin/kassiber-ui"; };
        cli = { type = "app"; program = "${cli}/bin/kassiber"; };
      };
    };
}
